import { IconTile, Sidebar, SidebarHeader, SidebarItem, SidebarSection } from '@strata/react';
import { IconLayoutDashboard, IconReceipt, IconSparkles } from '@strata/icons';

export function AppNav({ collapsed, onCollapsedChange }) {
  return (
    <Sidebar aria-label="Main" variant="floating" collapsed={collapsed} onCollapsedChange={onCollapsedChange}>
      <SidebarHeader logo={<IconTile tint="solid" size="sm"><IconSparkles /></IconTile>} title="Ledger" subtitle="Wealth dashboard" />
      <SidebarSection title="Overview">
        <SidebarItem href="/" icon={<IconLayoutDashboard />} isCurrent>Dashboard</SidebarItem>
        <SidebarItem href="/statements" icon={<IconReceipt />} count={3}>Statements</SidebarItem>
      </SidebarSection>
    </Sidebar>
  );
}
